```java
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class CarColorStats {
    private String color;
    private int count;

    public CarColorStats(String color, int count) {
        this.color = color;
        this.count = count;
    }

    public String getColor() {
        return color;
    }

    public int getCount() {
        return count;
    }
}

public class Car {
